'use strict';
(()=>{
 const $=id=>document.getElementById(id), form=$('create-form'), endpoint='/api/secretj-botfolio?action=';
 function theme(){try{document.documentElement.dataset.theme=localStorage.getItem('jh-theme')||'light';}catch{}}
 theme();$('theme').onclick=()=>{const t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;try{localStorage.setItem('jh-theme',t);}catch{}};
 function status(el,text,error=false){el.textContent=text;el.classList.toggle('error',error);}
 async function api(url,method='GET',body){const r=await fetch(url,{method,credentials:'same-origin',cache:'no-store',...(body!==undefined?{headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:method==='DELETE'?{headers:{'Content-Type':'application/json'},body:'{}'}:{})});let d;try{d=await r.json();}catch{throw Error('Service unavailable.');}if(!r.ok||!d.ok)throw Error(d.error||'Request failed.');return d;}
 const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 function button(label,fn){const b=el('button',label);b.type='button';b.onclick=async()=>{b.disabled=true;try{await fn(b);}catch(e){status($('status'),e.message,true);$('status').hidden=false;}finally{b.disabled=false;}};return b;}
 function publicUrl(id){return new URL('/botfolio-chat.html?id='+encodeURIComponent(id),location.origin).href;}
 async function copy(value,b){try{await navigator.clipboard.writeText(value);const old=b.textContent;b.textContent='Copied ✓';setTimeout(()=>{b.textContent=old;},1200);}catch{const box=el('textarea');box.value=value;box.readOnly=true;b.closest('.bot-card').append(box);box.select();}}
 async function refresh(){const d=await api(endpoint+'list');$('bots').replaceChildren();$('status').hidden=true;if(!d.ai_ready){$('status').hidden=false;status($('status'),'AI service is not configured yet. Existing portfolios can still be managed.',true);}
 if(!d.bots.length)$('bots').append(el('div','No portfolios yet. Create your first one below.','panel'));
 for(const bot of d.bots){const card=el('article',undefined,'bot-card');card.append(el('span',bot.published?'Published':'Private draft','tag'),el('h3',bot.name),el('p',bot.headline||'Professional AI portfolio'));const actions=el('div',undefined,'actions');
 if(bot.published){const link=el('a','Open chat ↗');link.href=publicUrl(bot.id);link.target='_blank';link.rel='noopener';actions.append(link,button('Copy link',b=>copy(publicUrl(bot.id),b)),button('Copy HTML',b=>copy('<iframe src="'+publicUrl(bot.id)+'" title="AI professional portfolio" width="100%" height="600" style="border:0;border-radius:16px" loading="lazy" referrerpolicy="no-referrer"></iframe>',b)));}
 actions.append(button(bot.published?'Unpublish':'Publish',async()=>{if(!bot.published&&!confirm('Publish this reviewed professional knowledge? Anyone with the link may ask the AI about it.'))return;await api(endpoint+'publish','PATCH',{id:bot.id,published:!bot.published,consent:!bot.published});await refresh();}),button('Delete',async()=>{if(confirm('Delete this portfolio and its indexed knowledge?')){await api(endpoint+'delete&id='+encodeURIComponent(bot.id),'DELETE');await refresh();}}));
 card.append(actions);if(bot.published){const url=el('input');url.readOnly=true;url.value=publicUrl(bot.id);url.setAttribute('aria-label','Public portfolio link');card.append(url);} $('bots').append(card);}
 }
 async function importFile(file){status($('form-status'),'Extracting CV text locally…');try{const text=await window.SecretJCVParser.extractText(file);if(!text.trim())throw Error('No text found. Paste your professional details instead.');if(text.length>18000)throw Error('CV is too long. Paste a shorter reviewed version.');form.elements.knowledge.value=text;form.elements.reviewed.checked=false;status($('form-status'),'Review the extracted text and remove private details before creating.');}catch(e){status($('form-status'),e.message,true);}}
 $('import-cv').onclick=async()=>{const b=$('import-cv');b.disabled=true;try{const d=await api('/api/secretj-data?scope=cv');if(!d.found)throw Error('No CV saved. Upload one or paste your details.');const f=d.file,bytes=Uint8Array.from(atob(f.base64),x=>x.charCodeAt(0));await importFile(new File([bytes],f.original_name,{type:f.mime_type}));}catch(e){status($('form-status'),e.message,true);}finally{b.disabled=false;}};
 $('upload').onchange=()=>{const file=$('upload').files[0];if(file)importFile(file);};form.elements.knowledge.addEventListener('input',()=>{form.elements.reviewed.checked=false;});
 form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('[type=submit]');b.disabled=true;status($('form-status'),'Indexing your reviewed knowledge…');try{await api(endpoint+'create','POST',{name:form.elements.name.value,headline:form.elements.headline.value,knowledge:form.elements.knowledge.value,reviewed:form.elements.reviewed.checked});form.reset();await refresh();status($('form-status'),'Private draft created. Publish it from My portfolios when ready.');}catch(e){status($('form-status'),e.message,true);}finally{b.disabled=false;}};
 (async()=>{try{const s=await api('/api/secretj-auth?action=session');if(!s.user){$('guest').hidden=false;$('status').hidden=true;return;}$('workspace').hidden=false;await refresh();}catch(e){status($('status'),e.message,true);$('guest').hidden=false;}})();
})();
